// Generated by OrchestKit Claude Plugin
// Created: 2026-07-31

// Turns a batch of dispatched JSON-RPC request/response pairs into first-party
// analytics events. Pure, so the whole property mapping is unit-testable
// without a request, a runtime, or the MCP route's module graph.
//
// Middleware already counts REACH on every agent surface (see
// lib/agent-surface.ts). MCP is the one surface where reach is not enough: what
// matters is whether an agent completes the initialize → tools/list →
// tools/call handshake, which tool it picks, and whether the call errored —
// none of which is visible from the request line, because every method arrives
// as a POST to the same path.

import type { ServerEvent, ServerEventProps } from "@/lib/analytics-server";
import { truncateQuery } from "@/lib/search-relevance";

const MCP_PATH = "/api/mcp";
const MAX_NAME = 64;

// Notifications and `ping` are transport chatter, not intent. Reporting them
// would triple the volume and tell us nothing about tool selection.
const REPORTED_METHODS: ReadonlySet<string> = new Set([
	"initialize",
	"tools/list",
	"tools/call",
]);

function asRecord(value: unknown): Record<string, unknown> | null {
	return typeof value === "object" && value !== null && !Array.isArray(value)
		? (value as Record<string, unknown>)
		: null;
}

function asString(value: unknown, max: number): string | null {
	return typeof value === "string" && value.length > 0
		? value.slice(0, max)
		: null;
}

export type RpcPair = { request: unknown; response: unknown };

/**
 * @param audience bounded per-request properties (ua family, accept family)
 *                 shared by every event in the batch.
 */
export function mcpTelemetryEvents(
	pairs: readonly RpcPair[],
	audience: ServerEventProps = {},
): ServerEvent[] {
	const events: ServerEvent[] = [];

	for (const { request, response } of pairs) {
		const req = asRecord(request);
		const method = asString(req?.method, MAX_NAME);
		if (!method || !REPORTED_METHODS.has(method)) continue;

		const params = asRecord(req?.params);
		const res = asRecord(response);
		const rpcError = asRecord(res?.error);
		const result = asRecord(res?.result);

		const properties: ServerEventProps = {
			...audience,
			method,
			// A tool that throws returns isError on the result, a bad method or an
			// unknown tool returns a JSON-RPC error. Both are failures.
			is_error: rpcError !== null || result?.isError === true,
		};
		if (typeof rpcError?.code === "number") {
			properties.error_code = rpcError.code;
		}

		if (method === "initialize") {
			const version = asString(params?.protocolVersion, MAX_NAME);
			if (version) properties.protocol_version = version;
			// Answers "which agent implementations have ever handshaked with us",
			// which today has no answer at all. Client names are a small closed set
			// in practice; capped anyway.
			const clientName = asString(asRecord(params?.clientInfo)?.name, MAX_NAME);
			if (clientName) properties.client_name = clientName;
		}

		if (method === "tools/call") {
			properties.tool = asString(params?.name, MAX_NAME) ?? "unknown";
			const args = asRecord(params?.arguments);
			const query = typeof args?.query === "string" ? args.query : null;
			if (query !== null) properties.query_len = query.length;

			const results = asRecord(result?.structuredContent)?.results;
			if (Array.isArray(results)) {
				properties.result_count = results.length;
				// Raw text only on a zero-result call — the same rule the browser
				// beacon follows. A query that matched nothing IS the content-gap
				// backlog; every other call carries only its length.
				if (results.length === 0 && query) {
					const truncated = truncateQuery(query);
					if (truncated) properties.query = truncated;
				}
			}
		}

		events.push({ name: "agent:mcp-call", path: MCP_PATH, properties });
	}

	return events;
}
